DROP TABLE IF EXISTS `cq_magictype`;
CREATE TABLE `cq_magictype` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `type` int(10) unsigned NOT NULL DEFAULT 0,
  `sort` int(10) unsigned NOT NULL DEFAULT 0,
  `name` varchar(32) NOT NULL DEFAULT '',
  `crime` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `ground` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `multi` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `target` int(10) unsigned NOT NULL DEFAULT 0,
  `level` int(10) unsigned NOT NULL DEFAULT 0,
  `use_mp` int(10) unsigned NOT NULL DEFAULT 0,
  `power` int(11) NOT NULL DEFAULT 0,
  `intone_speed` int(10) unsigned NOT NULL DEFAULT 0,
  `percent` int(10) unsigned NOT NULL DEFAULT 0,
  `step_secs` int(10) unsigned NOT NULL DEFAULT 0,
  `range` int(10) unsigned NOT NULL DEFAULT 0,
  `distance` int(10) unsigned NOT NULL DEFAULT 0,
  `status` bigint(20) NOT NULL DEFAULT 0,
  `need_prof` int(10) unsigned NOT NULL DEFAULT 0,
  `need_exp` int(11) NOT NULL DEFAULT 0,
  `need_level` int(10) unsigned NOT NULL DEFAULT 0,
  `use_xp` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `weapon_subtype` int(10) unsigned NOT NULL DEFAULT 0,
  `weapon_subtype_num` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `active_times` int(10) unsigned NOT NULL DEFAULT 0,
  `auto_active` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `floor_attr` int(10) unsigned NOT NULL DEFAULT 0,
  `auto_learn` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `learn_level` int(10) unsigned NOT NULL DEFAULT 0,
  `drop_weapon` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `use_ep` int(10) unsigned NOT NULL DEFAULT 0,
  `weapon_hit` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `use_item` int(10) unsigned NOT NULL DEFAULT 0,
  `next_magic` int(10) unsigned NOT NULL DEFAULT 0,
  `delay_ms` int(10) unsigned NOT NULL DEFAULT 0,
  `use_item_num` int(10) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `idx_magic_type_lvl` (`type`, `level`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

